198→      prompt: body.message,
199→      options: {
200→        model: modelName,
201→        systemPrompt: body.system_prompt,
202→        allowedTools: ["Task", "mcp__duckdb__execute_sql", "mcp__duckdb__ask_user_question"],
203→        permissionMode: "bypassPermissions",
204→        allowDangerouslySkipPermissions: true,
205→        maxTurns: 20,
206→        includePartialMessages: true,
207→        abortController,
208→        env: sdkEnv,
209→        stderr: (line: string) => {
210→          stderrLines.push(line);
211→          console.error(`[sidecar:cli] ${line}`);
212→        },
213→        ...(sdkAgents ? { agents: sdkAgents } : {}),
214→        ...(body.mcp_server_url
215→          ? {
216→              mcpServers: {
217→                duckdb: {
218→                  type: "sse" as const,
219→                  url: body.mcp_server_url,
220→                },
221→              },
222→            }
223→          : {}),
224→        ...(body.session_id ? { resume: body.session_id } : {}),
225→      },
226→    });
