      if (idleTimer) { clearTimeout(idleTimer); }
      idleTimer = setTimeout(() => {
        console.error(`[sidecar] SDK idle timeout (${SDK_IDLE_TIMEOUT_MS}ms) reached, aborting reqId=${requestId}`);
